CREATE TABLE IF NOT EXISTS module_instances (id BIGINT PRIMARY KEY GENERATED ALWAYS AS IDENTITY,module_key VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,module_type VARCHAR(40) NOT NULL,base_url VARCHAR(500),version VARCHAR(40),status VARCHAR(20) NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','connecting','healthy','degraded','disabled')),capabilities JSONB NOT NULL DEFAULT '[]'::jsonb,settings JSONB NOT NULL DEFAULT '{}'::jsonb,last_seen_at TIMESTAMP,last_error TEXT,created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_module_instances_status ON module_instances(status,last_seen_at);
